def p_xml(style, text):
    style_id = {"title": "Title", "h1": "Heading1", "h2": "Heading2", "p": "Normal", "li": "List"}.get(style, "Normal")
    body = escape(text)
    return (
        f'<w:p><w:pPr><w:pStyle w:val="{style_id}"/></w:pPr>'
        f'<w:r><w:t xml:space="preserve">{body}</w:t></w:r></w:p>'
    )


document = """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
  <w:body>
    {body}
    <w:sectPr>
      <w:pgSz w:w="11906" w:h="16838"/>
      <w:pgMar w:top="1134" w:right="1134" w:bottom="1134" w:left="1134"/>
    </w:sectPr>
  </w:body>
</w:document>
""".format(body="\n    ".join(p_xml(s, t) for s, t in BLOCKS))

